mapper.select:
SELECT , 
FROM lab l LEFT JOIN college c ON c.id = l.college_id
WHERE l.id = #{id}

SELECT , 
FROM lab l LEFT JOIN college c ON c.id = l.college_id
WHERE l.code = #{code}

SELECT , 
FROM lab l LEFT JOIN college c ON c.id = l.college_id


        AND (l.name LIKE CONCAT('%', #{keyword}, '%')
             OR l.code LIKE CONCAT('%', #{keyword}, '%')
             OR l.direction LIKE CONCAT('%', #{keyword}, '%'))

    AND l.status = #{status}
    AND l.college_id = #{collegeId}

ORDER BY l.college_id, l.id
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM lab l


        AND (l.name LIKE CONCAT('%', #{keyword}, '%')
             OR l.code LIKE CONCAT('%', #{keyword}, '%')
             OR l.direction LIKE CONCAT('%', #{keyword}, '%'))

    AND l.status = #{status}
    AND l.college_id = #{collegeId}

SELECT , , (SELECT COUNT(*) FROM mentor m WHERE m.lab_id = l.id AND m.enabled = 1) AS mentor_count, (SELECT COUNT(DISTINCT i.application_id) FROM application_intent i WHERE i.batch_id = #{batchId} AND i.mentor_id IN (SELECT m2.id FROM mentor m2 WHERE m2.lab_id = l.id)) AS applicant_count, (SELECT COUNT(*) FROM final_assignment fa WHERE fa.batch_id = #{batchId} AND fa.lab_id = l.id AND fa.status != 'REVOKED') AS confirmed_count, (l.total_quota - (SELECT COUNT(*) FROM final_assignment fa2 WHERE fa2.batch_id = #{batchId} AND fa2.lab_id = l.id AND fa2.status != 'REVOKED')) AS remaining_quota FROM lab l LEFT JOIN college c ON c.id = l.college_id
AND l.college_id = #{collegeId}
ORDER BY l.college_id, l.id

mapper.update:
UPDATE lab
SET college_id = #{collegeId}, code = #{code}, name = #{name}, intro = #{intro},
    direction = #{direction}, training_plan = #{trainingPlan}, requirements = #{requirements},
    contact = #{contact}, location = #{location}, cover_image = #{coverImage},
    total_quota = #{totalQuota}, status = #{status}
WHERE id = #{id}
